        query = query.Where(u =>
            u.Name.ToLower().Contains(s) ||
            u.Email.ToLower().Contains(s));
    }

    var total = await query.CountAsync();

    var items = await query
        .OrderBy(u => u.Name)
        .Skip((page - 1) * pageSize)
        .Take(pageSize)
        .Select(u => new UserDto { Id = u.Id, Name = u.Name, Email = u.Email })
        .ToListAsync();

