public ListNode? CycleStart(ListNode? head)
{
    var slow = head; var fast = head;
    while (fast?.Next != null)
    {
        slow = slow!.Next;
        fast = fast.Next.Next;
        if (slow == fast) break;
    }
    if (fast?.Next is null) return null;   // no cycle

    slow = head;
    while (slow != fast)
    {
        slow = slow!.Next;
        fast = fast!.Next;
    }
    return slow;   // start of cycle
}

