export function lengthOfLongestSubstring(s: string): number {
  const lastSeen = new Map<string, number>();
  let l = 0, best = 0;

  for (let r = 0; r < s.length; r++) {
    const ch = s[r];
    if (lastSeen.has(ch) && lastSeen.get(ch)! >= l) {
      l = lastSeen.get(ch)! + 1;
    }
    lastSeen.set(ch, r);
    best = Math.max(best, r - l + 1);
  }
  return best;
}

