// === Choosing between switchMap, mergeMap, concatMap, exhaustMap ===
//
//  switchMap   — cancel the previous; only the latest matters
//                (search-as-you-type, route changes)
//
//  mergeMap    — fire ALL in parallel, order not preserved
//                (upload several files at once)
//
//  concatMap   — queue, run one after another
//                (sequential API calls where order matters)
//
//  exhaustMap  — IGNORE new inputs while one is running
//                (login button — prevent double-submit)

// === forkJoin vs combineLatest ===
//   forkJoin     — waits for ALL to COMPLETE, then emits ONCE
//                  (parallel one-shot HTTP calls — like Promise.all)
//   combineLatest— emits whenever ANY source emits, with the latest of each
//                  (live data combined from multiple streams)
forkJoin({
  user: this.api.getUser(id),
  orders: this.api.getOrders(id)
}).subscribe(({ user, orders }) => { ... });

